<template>
  <el-dialog
    title="一键导游全局设置"
    :visible.sync="dialogFormVisible"
    width="580px"
    :append-to-body="true"
  >
    <el-form :model="form" ref="tourSetForm" :rules="rules">
      <el-form-item label="导游标题" :label-width="formLabelWidth" prop="title">
        <el-input
          v-model="form.title"
          autocomplete="off"
          min="0"
          size="small"
          placeholder=""
        ></el-input>
      </el-form-item>
      <el-form-item
        label="设置开始/结束图片"
        :label-width="formLabelWidth"
        class="set-st-et-img-item"
      >
        <vr-upload
          uploadClass="img-container"
          tip="建议尺寸：500 X 500"
          listType
          :cropImg="true"
          :cropDialogModal="false"
          :autoCropWidth="500"
          :autoCropHeight="500"
          :autoUpload="false"
          :fileList="[
            {
              name: form.title,
              url: form.startImgFull,
              path: form.startImg,
            },
          ]"
          @onSuccess="onStartImgUploadSuccess"
        />
        <vr-upload
          uploadClass="img-container"
          tip="建议尺寸：500 X 500"
          listType
          :cropImg="true"
          :cropDialogModal="false"
          :autoCropWidth="500"
          :autoCropHeight="500"
          :autoUpload="false"
          :fileList="[
            {
              name: form.title,
              url: form.endImgFull,
              path: form.endImg,
            },
          ]"
          @onSuccess="onEndImgUploadSuccess"
        />
      </el-form-item>
      <div class="fix-div">
        <el-form-item label="循环播放导游" label-width="140">
          <el-checkbox
            v-model="form.loopPlay"
            true-label="1"
            false-label="0"
          ></el-checkbox>
        </el-form-item>
        <el-form-item
          label="播放结束后回到起始场景"
          :label-width="formLabelWidth"
        >
          <el-checkbox
            v-model="form.endToStart"
            true-label="1"
            false-label="0"
          ></el-checkbox>
        </el-form-item>
      </div>
      <div class="fix-div">
        <el-form-item label="文字位置" label-width="120">
          <el-radio-group v-model="form.txtPosition" size="small">
            <el-radio-button label="top">上</el-radio-button>
            <el-radio-button label="bottom">下</el-radio-button>
          </el-radio-group>
        </el-form-item>
        <el-form-item label="文字字号" label-width="120">
          <el-select
            v-model="form.txtSize"
            placeholder="请选择"
            style="width: 120px"
          >
            <el-option
              v-for="item in txtSizeOptions"
              :key="item.value"
              :label="item.label"
              :value="item.value"
            >
            </el-option>
          </el-select>
        </el-form-item>
      </div>
    </el-form>
    <div slot="footer" class="dialog-footer">
      <el-button @click="dialogFormVisible = false">取 消</el-button>
      <el-button type="primary" @click="onSave">确 定</el-button>
    </div>
  </el-dialog>
</template>

<script>
import { getTourGlobalSet, tourGlobalSet } from '@/api/vr'

const defaultForm = {
  title: '',
  startImg: '',
  startImgFull: '',
  endImg: '',
  endImgFull: '',
  loopPlay: 1,
  endToStart: 1,
  txtPosition: 'bottom',
  txtSize: '12',
}
export default {
  name: 'TourGlobalSettingDialog',
  components: {
    VrUpload: () => import('@/components/VrUpload.vue'),
  },
  data() {
    return {
      dialogFormVisible: false,
      form: Object.assign({}, defaultForm),
      formLabelWidth: '170px',
      productId: null,
      txtSizeOptions: [
        {
          value: '12',
          label: '12',
        },
        {
          value: '14',
          label: '14',
        },
        {
          value: '16',
          label: '16',
        },
        {
          value: '18',
          label: '18',
        },
        {
          value: '20',
          label: '20',
        },
        {
          value: '22',
          label: '22',
        },
        {
          value: '24',
          label: '24',
        },
      ],
      rules: {
        title: [
          { required: true, message: '导游标题必须填写', trigger: 'blur' },
          {
            min: 2,
            max: 200,
            message: '长度在 2 到 200 个字符',
            trigger: 'blur',
          },
        ],
      },
    }
  },
  mounted() {},
  methods: {
    init(productId) {
      this.productId = productId
      this.getTourGlobalSet()
      this.dialogFormVisible = true
    },
    async getTourGlobalSet() {
      const tour = await getTourGlobalSet(this.productId)
      if (tour) {
        this.form = tour
      }
    },
    onStartImgUploadSuccess(data) {
      this.form.startImg = data.path
    },
    onEndImgUploadSuccess(data) {
      this.form.endImg = data.path
    },
    onSave() {
      this.$refs.tourSetForm.validate((valid) => {
        if (valid) {
          tourGlobalSet(this.productId, this.form).then(() => {
            this.$message.success('设置成功')
            this.form = Object.assign({}, defaultForm)
            this.dialogFormVisible = false
            this.productId = null
            this.$refs.tourSetForm.resetFields()
          })
        } else {
          return false
        }
      })
    },
  },
}
</script>

